{
  "name": "数字万用表校准系统",
  "name_en": "Digital Multimeter Calibration System",
  "manufacturer": "",
  "description": "用于数字万用表校准与核查的实验室测试系统，通常由待校万用表、已校准的参考万用表以及电源或激励源组成，用于施加已知电信号并比较测量结果，从而完成校准和精度检查。",
  "description_en": "A laboratory test system for calibrating and verifying digital multimeters. It typically consists of the multimeter under test, a calibrated reference multimeter, and a power supply or stimulus source used to apply known electrical signals and compare readings for calibration and accuracy checks.",
  "actions": [
    {
      "action_name": "auto-init_ui",
      "description": "初始化万用表校准系统的操作界面",
      "description_en": "Initialize the operating interface for the multimeter calibration system."
    },
    {
      "action_name": "auto-connect_multimeter_to_calibrate",
      "description": "连接待校准的万用表",
      "description_en": "Connect the multimeter that will be calibrated."
    },
    {
      "action_name": "auto-connect_calibrated_multimeter",
      "description": "连接已校准的参考万用表",
      "description_en": "Connect the calibrated reference multimeter."
    },
    {
      "action_name": "auto-connect_power_supply",
      "description": "连接用于提供校准信号的电源",
      "description_en": "Connect the power supply used to provide calibration signals."
    },
    {
      "action_name": "auto-calibrate_multimeter",
      "description": "执行万用表校准",
      "description_en": "Perform multimeter calibration."
    },
    {
      "action_name": "auto-check_calibration",
      "description": "检查万用表校准结果",
      "description_en": "Check the multimeter calibration result."
    }
  ],
  "tag_hints": [
    "digital multimeter calibration",
    "reference multimeter",
    "electrical measurement verification",
    "power supply stimulus",
    "instrument calibration"
  ]
}

